css..hero-overlay:
position:absolute;inset:0;z-index:1;
/* затемнення зверху, щоб білий текст читався на будь-якому кадрі відео */
background:linear-gradient(180deg,
  rgba(8,9,14,.74) 0%,
  rgba(8,9,14,.66) 26%,
  rgba(8,9,14,.44) 45%,
  rgba(8,9,14,.14) 62%,
  rgba(8,9,14,.10) 80%,
  rgba(8,9,14,.44) 100%);
pointer-events:none;

css..aurora-bg:
position:relative;overflow:hidden;
background:
  url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg'><filter id='n'><feTurbulence type='fractalNoise' baseFrequency='0.7' numOctaves='2' stitchTiles='stitch'/></filter><rect width='100%25' height='100%25' filter='url(%23n)'/></svg>"),
  radial-gradient(130% 100% at 88% -12%, rgba(198,146,92,.32) 0%, rgba(198,146,92,.09) 38%, transparent 62%),
  radial-gradient(110% 90% at -8% 112%, rgba(150,96,58,.22) 0%, transparent 58%),
  linear-gradient(155deg,#1b1512 0%,#0d0a08 52%,#17110c 100%);
background-size:160px 160px, auto, auto, auto;
background-blend-mode:soft-light, normal, normal, normal;
box-shadow:inset 0 1px 0 rgba(255,255,255,.07);

css..aurora-bg::before:
width:min(420px,72%);aspect-ratio:1/1;top:-32%;right:-14%;
background:radial-gradient(circle at 50% 50%, rgba(205,150,95,.34) 0%, transparent 68%);
animation:glow-drift-1 13s ease-in-out infinite;

css..aurora-bg::after:
width:min(380px,64%);aspect-ratio:1/1;bottom:-30%;left:-12%;
background:radial-gradient(circle at 50% 50%, rgba(150,96,58,.24) 0%, transparent 68%);
animation:glow-drift-2 17s ease-in-out infinite;

